insert into cost_components (name, calc_type, percentage, base_components, state, notes, enabled, sort_order, deduction_calc_type, fixed_calc_method, fixed_duty_components, code, formula, day_driver, formula_mode, formula_expression, formula_version, party, description)
select '10% of Basic + DA', 'percentage', 10, '[{"label":"Basic","operator":"+"},{"label":"DA","operator":"+"}]'::jsonb, 'N/A', '', true, 0, 'earned_salary', 'flat', '{}'::text[], 'ER_BASIC_DA_10', '{}'::jsonb, 'ratio', 'advanced', '(basic + da) * 0.10', 1, 'employer', '10% of Basic plus DA, no cap.'
